import{_ as n,c as s,b as t,e as p,h as l,w as i,j as o,a as r}from"./app-BIfOkl3-.js";const c="/assets/img/Guilty/image.png",m={};function d(h,e){const a=o("font");return r(),s("div",null,[e[1]||(e[1]=t("link",{rel:"stylesheet",href:"/css/font-style.css"},null,-1)),e[2]||(e[2]=t("img",{src:c,style:{display:"block",margin:"0 auto"}},null,-1)),p(a,{style:{"text-align":"center"}},{default:i(()=>e[0]||(e[0]=[t("p",null,"（图片描述为书中拉斯科尔尼科夫幻想成为的人——斯维德利盖洛夫，对面站着的是他的亡妻）",-1)])),_:1,__:[0]}),e[3]||(e[3]=l('<p> 罗季昂·曼内奇·拉斯科尔尼科夫，一个受限于自己尊严的的人，一个矛盾的人，一个活在自我世界的人，一个激进主义者，一个活生生的人。他是我的真实写照，同时也是我既可怜又憎恶的人。</p><h2 id="巧合-不-是心理暗示" tabindex="-1"><a class="header-anchor" href="#巧合-不-是心理暗示"><span>巧合？不！是心理暗示！</span></a></h2><p> 当拉斯科尔尼科夫认为自己可以成为拿破仑时，故事就已经开始了。他认为自己是一个无比强大的人，需要去牺牲一些“人”从而达成一番成就。他活在自己的理论中无法自拔，这样的自我精神暗示导致在前文中处处提到“就像是巧合一样/就像是上帝需要他这么做一样”。可结局可想而知，他错了，错的一塌糊涂，甚至直到最后进入监狱也没有认清为什么会这样？为什么自己会失败，他把所有的原因归结于不够谨慎计划不够完美。可如果一个理论、一个精神、一个想法从一开始就是错的，那他无论如何都不会成功！</p><p> 所以他杀了人！他杀死了一个放高利贷的人和一个更加无辜的人！放高利贷的人罪恶么？罪恶可罪不至死！他很慌张，因为当他杀死了一个更加无辜的人。他是一个懦夫，一个懦夫却想要成就一番这样的牺牲换来的事业，这是更加愚蠢的做法。</p><p> 当他站在上完房门锁的后面，内心是激动、后悔和不知所措的，就像一个犯了错的孩子，我十分熟悉这样的感觉。事实上，当一个人需要一个东西却无法得到时，没有正确的引导会滋生强烈的获取欲望和冲动，直致酿成大祸！是的，我也经历过，曾经的我也是这么想的这么做的，当我看到罗季昂·曼内奇·拉斯科尔尼科夫时，我看到的不是一个文字、一个人物，而是我。我痛恨这样的文字击穿我的内心，可不得不承认这就是我，那样的矛盾那么的可笑。仅是为了一个理论、一个简简单单的名誉、仅为了活着。</p><p> 或者，我可以从他的梦入手？看看他的梦吧，当他看到一头牲畜被一群喝醉了的人围着鞭打，看看他/它吧。究竟是什么样的环境才可以造就这样的人呢？拿头牲畜就这样蹲着、叫喊着...罗季昂想要去拦住他们？他同情它？哈哈哈哈哈，究竟是谁在同情？只是一个可怜人在可怜另一个“人”罢了。他的爸爸在一旁拉住他，就像他梦到的那样......我无法想象这个梦的后续是什么。但或许，我也可以十分轻描淡写的说，不就是一个牲畜么？倒也不至于我们去关心和顾虑。可是谁！是谁站在广场上抱着牲畜痛哭？那是我...那就是我!</p><h2 id="煎熬、后悔与自尊" tabindex="-1"><a class="header-anchor" href="#煎熬、后悔与自尊"><span>煎熬、后悔与自尊</span></a></h2><p> 我们来看看他吧，一个 20 多岁的的学者，好友给他介绍工作被推脱，在杀害两人后的日子里变得疑神疑鬼甚至开始出现发烧和生病，哈哈哈哈哈哈，真是一个懦夫！事后还要把自己用来杀人的斧子擦洗干净，急急忙忙的还回去。还有还有，拿来的钱偷偷压在一处地方的石头下，哈哈哈哈哈哈哈真是可笑。这样也要杀人么？感觉像是一个毫无经验的新手，你看看斯维德利盖洛夫呢？你应该和他好好学学，杀人不眨眼，坏事做尽。你真的是拿破仑么？你的理论和实践真的一致么？你看看你的双手和裤脚是不是还残留有愚钝留下的痕迹？</p><p> 答案就在眼前，我看到他在沙发上头脑恍惚。是的，我应该像杨·凡·艾克一样留下一句：“我曾在场”。就像现在这般得意！我唾弃他的自尊就像在唾弃曾经的我一样，我看到他还在做着毫无意义的收拾，墙角啊、大衣啊什么的。你不觉得很有趣么？以陀翁的上帝视角，这就是他本人啊！我无需多言，这就是本人！活生生的人，无论是我，罗季昂、还是陀思妥耶夫斯基！</p><p> 你看这笔下的人物内心的描写？他何尝不想回到那天，他就不应该去杀人，不应该去谋划，不应该听从酒馆里那群人的说图。但是现在，你觉得我们还能回去么？我们手上都沾满鲜血和泥土，直到死亡那天，直到审判庭下发审判诏书，直到严寒的冷冬到来，或许我们才可以解脱。在这之前，你想先放下？抱歉，你放不下！甚至认为放下可耻，有伤自尊！会羞耻会难受会觉得自己十分愚蠢。直到你想，你希望，你完全能像这样跪下亲吻大地！你才能获得内心的解脱和救赎！</p><p> 来吧，现在让我们拥抱在一起。究竟是这灵魂的解脱能换取一丝救赎，还是虚妄的尊严可以带你走向胜利！让我们拭目以待！</p><h2 id="自杀和自首" tabindex="-1"><a class="header-anchor" href="#自杀和自首"><span>自杀和自首</span></a></h2><p> 我疯了么？不...不是的，我并没有疯掉，恰是我看到了曾经的我，那面镜子，肮脏的镜子，我才会这样口无遮拦的羞辱。可怜的罗季昂，你直到最后进入监狱也并没有明晰这是为什么...你为什么会失败。当得知斯维德利盖洛夫自杀身亡后，他内心的最后一根稻草彻底被切断，根须拔出的那一瞬间，看到闻到的...是腐烂和恶臭！常人无法看到他的样子，看到了也无法理解，只有经历过的才知道。那是混世大魔王，念想是毁灭世界。这也正是斯维德利盖洛夫本人——罗季昂的理想中的自己。</p><p> 他的世界观崩塌了么？是的，崩塌了。但他陷入了沉默，哈哈哈哈哈沉默是金。他在思考为什么，可越是思考，越是糊涂。像他这样的人有什么好同情地？即使他救过一些人，帮助过一些人。但是罪孽就摆在这里。你要为他辩护么？我会！接下来是我的陈述词！</p><p> 还记得那场梦吧，那个牲畜就是他本人。很惊讶？但是你想一样呢？想一想一个自幼失去父亲，被母亲带大的人会是什么样的？他的三观正常么？多少会有罪孽吧，但不全是的吧。不然他为什么会去救助同学，为什么会去拯救火灾里的孩子？当索尼娅出现在他生命中时，他并没有出现厌恶或者说讨厌吧，这是值得称赞的。或者说，他本人并没有意识到他自己在理论上的错误，犯了当时俄国众多学者犯得错误，那些激进的学生希望以此来证明自己。呵呵可笑又可悲...</p><p> 当他和索尼娅一起坐在西伯利亚的荒原上时，当他再一次做梦看到瘟疫席卷时，或许他已经明白自己的问题。他选择跪下来倒在索尼娅的面前痛哭，直到那一刻，他的灵魂才得到真正的救赎，他才真切的明白那些冷眼和躲避是多么的愚蠢。</p><h2 id="我-不-是我" tabindex="-1"><a class="header-anchor" href="#我-不-是我"><span>我？不，是我</span></a></h2><p> 我写下这些字的时候，手指在发抖。不是因为冷，是因为怕。怕你——罗季昂·曼内奇·拉斯科尔尼科夫——就这样从书页里爬出来，掐住我的喉咙说：“你就是我。”我知道，我躲不掉的。</p><p> 你问我后来怎样了？后来，我在西伯利亚的荒原上，跪在索尼娅的腿边，把脸埋进她的围裙里，哭得像个被遗弃的孩子。不是因为顿悟，不是因为理论终于崩塌——那些东西早就在我心里碎成渣了。连自尊都提不动了，终于承认：我他妈的就是一个凡人。</p><p> 至于那个瘟疫之梦吗？每个人手里都举着自己的真理，互相砍杀。我醒来的时候，额头上全是冷汗，嘴里苦得像吞了砒霜。我忽然想到——我不就是那个病人吗？我把“非凡的人”当成免罪金牌，把杀人当作数学题，把别人的生命当作算盘上的珠子。可算盘打到最后，珠子碎了，手指被割破，流出来的血和你我一样是红的。不是蓝色的，不是金色的。是红色的，腥的。</p><p> 你知道我什么时候真正活过来的吗？不是噩梦之后，不是跪地痛哭的时候。是有一天，一个粗鲁的囚犯——就是那个以前见我就吐口水的家伙——走过来，递给我半块黑面包，说：“嘿，知识分子，你也没那么讨厌。”我接过来的时候，手抖得厉害。不是因为感动，是因为我终于听懂了——一个人不需要成为拿破仑，才值得另一块面包。</p><p> 所以，别再说“拉斯科尔尼科夫”了。说吧，说我。说你。说那个在深夜翻来覆去、一边痛恨自己的懦弱一边又舍不得丢掉自尊的你。说那个考了试觉得不够好就恨不得把自己钉在墙上的你。说那个明明想拥抱，却偏要摆出一副“我不需要任何人”表情的你。</p><p> 我就是你。你就是我。</p><p> 现在，这本书翻到了最后一页。拉撒路已经走出了坟墓，裹尸布还缠在身上，但他已经在走了。我们也一样。脚下的路还是那条冻土路，风还是那个西伯利亚的风。但如果你愿意，可以弯下腰，捡起一块石头，放在路边，当作来过、哭过、活过的记号。</p><p> 我不需要你再写下去了。因为接下来的故事，是我自己来写。</p><p> 用一支笔，或者用活着本身。</p>',26))])}const u=n(m,[["render",d]]),g=JSON.parse('{"path":"/posts/BookReview/%E7%BD%97%E5%AD%A3%E6%98%82%C2%B7%E6%9B%BC%E5%86%85%E5%A5%87%C2%B7%E6%8B%89%E6%96%AF%E7%A7%91%E5%B0%94%E5%B0%BC%E7%A7%91%E5%A4%AB.html","title":"罗季昂·曼内奇·拉斯科尔尼科夫","lang":"en-US","frontmatter":{"title":"罗季昂·曼内奇·拉斯科尔尼科夫","description":"罗季昂·曼内奇·拉斯科尔尼科夫","date":"2026-04-15T00:00:00.000Z","timeline":true,"head":[["meta",{"name":"keywords","content":"我、intj、自尊、贱人"}],["meta",{"name":"description","content":"罗季昂·曼内奇·拉斯科尔尼科夫"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["书评"]},"headers":[{"level":2,"title":"巧合？不！是心理暗示！","slug":"巧合-不-是心理暗示","link":"#巧合-不-是心理暗示","children":[]},{"level":2,"title":"煎熬、后悔与自尊","slug":"煎熬、后悔与自尊","link":"#煎熬、后悔与自尊","children":[]},{"level":2,"title":"自杀和自首","slug":"自杀和自首","link":"#自杀和自首","children":[]},{"level":2,"title":"我？不，是我","slug":"我-不-是我","link":"#我-不-是我","children":[]}],"git":{"updatedTime":1776417794000,"contributors":[{"name":"qwp_p","username":"","email":"qwp20060309@outlook.com","commits":1}],"changelog":[{"hash":"45179df3db8c10aa860596802eb9fc8156c9abbe","time":1776417794000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"new post"}]},"filePathRelative":"posts/BookReview/罗季昂·曼内奇·拉斯科尔尼科夫.md","excerpt":"<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<img src=\\"/assets/img/Guilty/image.png\\" style=\\"display: block;margin: 0 auto;\\">\\n\\n<p> 罗季昂·曼内奇·拉斯科尔尼科夫，一个受限于自己尊严的的人，一个矛盾的人，一个活在自我世界的人，一个激进主义者，一个活生生的人。他是我的真实写照，同时也是我既可怜又憎恶的人。</p>\\n<h2>巧合？不！是心理暗示！</h2>\\n<p> 当拉斯科尔尼科夫认为自己可以成为拿破仑时，故事就已经开始了。他认为自己是一个无比强大的人，需要去牺牲一些“人”从而达成一番成就。他活在自己的理论中无法自拔，这样的自我精神暗示导致在前文中处处提到“就像是巧合一样/就像是上帝需要他这么做一样”。可结局可想而知，他错了，错的一塌糊涂，甚至直到最后进入监狱也没有认清为什么会这样？为什么自己会失败，他把所有的原因归结于不够谨慎计划不够完美。可如果一个理论、一个精神、一个想法从一开始就是错的，那他无论如何都不会成功！</p>"}');export{u as comp,g as data};
